package tv.vela.launcher;
import android.app.*;import android.os.*;import android.database.*;import android.database.sqlite.*;import java.io.*;import java.util.*;import org.json.*;
/** Explicit device diagnostic: refreshes only Vela's public programme cache; never tunes or writes system channels. */
public final class XmlTvDeviceProbe extends Instrumentation {
 static String socket(int family){try{java.io.FileDescriptor fd=android.system.Os.socket(family,android.system.OsConstants.SOCK_STREAM,0);android.system.Os.close(fd);return "OK";}catch(Exception e){return e.toString();}}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();JSONObject report=new JSONObject();long start=SystemClock.elapsedRealtime();try{report.put("uid",android.os.Process.myUid()).put("groups",new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("/proc/self/status")),"UTF-8")).put("socket4",socket(android.system.OsConstants.AF_INET)).put("socket6",socket(android.system.OsConstants.AF_INET6));List<LiveTvData.Channel> channels=new LiteAntennaData(getTargetContext()).channels(new CancellationSignal());getTargetContext().getSharedPreferences("lite_tv",0).edit().putBoolean("online_guide",true).commit();LiteXmlTvGuide guide=new LiteXmlTvGuide(getTargetContext());guide.invalidate();report.put("refreshed",guide.refresh(channels,new CancellationSignal()));File file=new File(getTargetContext().getCacheDir(),"antenna-epg/programmes.db");report.put("database_bytes",file.length());try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor c=db.rawQuery("SELECT COUNT(*) FROM programmes",null)){if(c.moveToFirst())report.put("programmes",c.getInt(0));}long now=System.currentTimeMillis()/1000;Map<String,List<LiveTvData.Programme>> read=guide.read(channels.subList(0,Math.min(6,channels.size())),now,now+10800,new CancellationSignal());JSONArray visible=new JSONArray();for(LiveTvData.Channel c:channels.subList(0,Math.min(6,channels.size())))visible.put(new JSONObject().put("name",c.name).put("programmes",read.getOrDefault(c.id,Collections.emptyList()).size()));report.put("first_six",visible);result.putString("result","Public EPG imported; "+report.optInt("programmes")+" programme rows");}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));try{report.put("error",android.util.Log.getStackTraceString(error));}catch(Exception ignored){}}try{report.put("elapsed_ms",SystemClock.elapsedRealtime()-start);try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"xmltv-device.json"))){out.write(report.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}finish(result.containsKey("error")?1:-1,result);}
}
